import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.BlfGB29P.js";const r="/images/logic-studio/user-guide/blocks-js-en.png",g=JSON.parse('{"title":"Blocks JS","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/blocks-js.md","filePath":"en/projects/logic-studio/user-guide/blocks-js.md","lastUpdated":1795861737000}'),n={name:"en/projects/logic-studio/user-guide/blocks-js.md"};function i(l,e,d,h,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="blocks-js" tabindex="-1">Blocks JS <a class="header-anchor" href="#blocks-js" aria-label="Permalink to &quot;Blocks JS&quot;">​</a></h1><h2 id="entitaetsauswahl-kompakte-trigger" tabindex="-1">Change triggers and entity selection <a class="header-anchor" href="#entitaetsauswahl-kompakte-trigger" aria-label="Permalink to &quot;Change triggers and entity selection {#entitaetsauswahl-kompakte-trigger}&quot;">​</a></h2><p>Under <strong>Trigger</strong>, choose a trigger for one entity, several entities or an attribute. Since <strong>0.1.135</strong>, these blocks use compact vertical rows. Long captions are shortened; saved IDs remain complete.</p><ol><li>Click the entity field in the multiple-entity trigger. Search by name or ID; select or deselect multiple results.</li><li><strong>Apply</strong> saves the selection. <strong>Close</strong> discards unconfirmed changes. Existing comma/whitespace-separated lists remain compatible.</li><li>Use the <strong>changed</strong> condition and put the logic and debug output inside the trigger.</li><li>Save and start <strong>Play</strong>. The contents run again when the state changes. Standalone blocks run only at startup.</li></ol><p>Selection grants no runtime permissions. Watched entities require READ permission; output targets still require WRITE. For switches, <strong>State of entity</strong> returns <code>on</code>/<code>off</code>. <strong>Entity exists</strong> only checks existence.</p><p><strong>Verified:</strong> 285 blocks, 51 direct entity fields and 80 local tests. Selection and compact rows checked in DE/EN/FR; no HA live test for 0.1.135.</p><h2 id="sensorzustand-setzen" tabindex="-1">Set sensor state <a class="header-anchor" href="#sensorzustand-setzen" aria-label="Permalink to &quot;Set sensor state {#sensorzustand-setzen}&quot;">​</a></h2><h3 id="sensor-dezimalzahl" tabindex="-1">Enter decimal values directly <a class="header-anchor" href="#sensor-dezimalzahl" aria-label="Permalink to &quot;Enter decimal values directly {#sensor-dezimalzahl}&quot;">​</a></h3><p>Since <strong>0.1.134</strong>: Choose <strong>System → Set sensor state · Decimal number</strong>, select a sensor and enter the value directly. The default is <code>0.5</code>; enter values such as <code>33.25</code> using a decimal point. Values are not rounded to integers and survive saving and reloading. The existing value-input block remains available. WRITE permission and sensor attributes are handled in the same way. Blocks A requires the running Studio app.</p><p><strong>Verified:</strong> 72 local tests plus, after backup on HA 2026.11.3, <code>0.5</code> and <code>33.25</code> through Blocks JS Play and the generated and inspected Blocks A event data. Both fields were confirmed after reloading; settings and attributes were retained.</p><p>From <strong>0.1.133</strong>, <strong>System</strong> includes <strong>Set sensor state</strong>. Select an existing <code>sensor.*</code> using HA-style selection and connect a number, text or calculation to the value input. Numbers must be finite; text is limited to 255 characters.</p><p>The sensor requires WRITE permission, for example in <code>runtime_write_entities</code>. Example generated code:</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ha.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setSensorState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sensor.example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Test run</strong> simulates the write. <strong>Save → Play</strong> runs it in the Studio runtime. Unit, device class and other attributes are retained. No device is controlled and no persistent sensor is created. The owning integration may replace the value later. Missing WRITE permissions and write errors appear in the runtime log.</p><p>In the backed-up HA live test, the calculation produced <strong>42 W</strong>. A subsequent write was rejected after removing the temporary permission; the original permissions were preserved.</p><h2 id="first-example" tabindex="-1">First example <a class="header-anchor" href="#first-example" aria-label="Permalink to &quot;First example&quot;">​</a></h2><p>The test run reads a simulated entity state and writes it to the log.</p><ol><li>Choose <strong>New project → Blocks JS</strong>. Open <strong>System</strong> and drag <strong>Log</strong> into the workspace.</li><li>Drag <strong>State of</strong> from the same category into the open input on the log block. Select your test entity. The screenshot uses <code>binary_sensor.bewegung</code>.</li><li>Start a <strong>test run</strong> and open the <strong>Log</strong>. The demo shows the state and message <code>on</code>. This script only reads and logs the value.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-js-en.png"><img src="'+r+'" alt="Blocks JS with an entity state block and the resulting log"></a></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="system-actions-and-sendto" tabindex="-1">System, Actions and Sendto <a class="header-anchor" href="#system-actions-and-sendto" aria-label="Permalink to &quot;System, Actions and Sendto&quot;">​</a></h3><p>Read states, control approved targets, message scripts or query history. Dynamic inputs can use an entity ID from a loop.</p><h3 id="triggers-time-and-timeouts" tabindex="-1">Triggers, time and timeouts <a class="header-anchor" href="#triggers-time-and-timeouts" aria-label="Permalink to &quot;Triggers, time and timeouts&quot;">​</a></h3><p>Start on state changes, sun events or schedules. Use simple and named CRON jobs, delays, intervals and stop blocks.</p><h3 id="value-blocks" tabindex="-1">Value blocks <a class="header-anchor" href="#value-blocks" aria-label="Permalink to &quot;Value blocks&quot;">​</a></h3><p>Conversion, objects, logic, math, text, lists and colors produce values. Loops repeat operations.</p><h3 id="variables-and-functions" tabindex="-1">Variables and functions <a class="header-anchor" href="#variables-and-functions" aria-label="Permalink to &quot;Variables and functions&quot;">​</a></h3><p>Use variables for intermediate values and functions for reusable steps and return values.</p><h3 id="iobroker-import" tabindex="-1">ioBroker import <a class="header-anchor" href="#iobroker-import" aria-label="Permalink to &quot;ioBroker import&quot;">​</a></h3><p>In Expert mode, paste the export and check the report. Map entities explicitly and read each block&#39;s guidance.</p><h3 id="check-whether-a-computed-iobroker-id-exists" tabindex="-1">Check whether a computed ioBroker ID exists <a class="header-anchor" href="#check-whether-a-computed-iobroker-id-exists" aria-label="Permalink to &quot;Check whether a computed ioBroker ID exists&quot;">​</a></h3><p>If your ioBroker script builds an ID from several text fragments, use the imported <code>state_exists_var</code> block to check it.</p><ol><li>In the import review, enter the complete computed ioBroker ID and its HA entity ID in <strong>ID mapping (JSON)</strong>, for example <code>{&quot;0_userdata.0.garden.pump&quot;:&quot;switch.garden_pump&quot;}</code>. The imported block also has this field.</li><li>Allow the mapped entity under <code>runtime_read_entities</code> in the app settings if it has no write permission yet.</li><li>Save the project and select <strong>Play</strong>. An existing HA entity returns <code>true</code>, and a mapped entity that is absent returns <code>false</code>. If the computed ID has no entry, the run stops and the log names that ID. Add the mapping on the block and run it again.</li></ol><h3 id="import-an-iobroker-data-point-as-an-ha-helper" tabindex="-1">Import an ioBroker data point as an HA helper <a class="header-anchor" href="#import-an-iobroker-data-point-as-an-ha-helper" aria-label="Permalink to &quot;Import an ioBroker data point as an HA helper&quot;">​</a></h3><p>If your Blockly export includes the <strong>Create data point</strong> block (<code>createState</code>), you can store its value in a Home Assistant helper. The helper appears in Home Assistant under <strong>Settings → Devices &amp; services → Helpers</strong>.</p><ol><li>Open <strong>Expert tools → Paste ioBroker export</strong>, paste the export, and check the import.</li><li>Choose one of the three options for the ioBroker ID: <ul><li><strong>Map helper</strong> uses an existing helper and keeps its current value.</li><li><strong>Create helper</strong> suggests a toggle, number, or text helper based on the data type. Check and confirm the name. Creating it requires an HA administrator account. A supported fixed initial value is applied once. For a calculated initial value, you can prepare a helper in HA and map it yourself.</li><li><strong>Map later</strong> leaves the mapping open. Open the project and select a compatible HA entity in the imported block before starting the script.</li></ul></li><li>Check that the blocks that create, read, and update the same ioBroker ID all point to the same HA entity. Open the import as a project and save it.</li><li>Allow the helper in the app options under <code>runtime_read_entities</code> and also under <code>runtime_write_entities</code> for updates. Use <strong>Play</strong> to start the saved script. The script reads the helper’s current value, including changes you make in Home Assistant.</li></ol><p>The example creates a number helper with <strong>17</strong>. On the first start, the script logs <strong>17</strong> and writes <strong>42</strong>. After a script restart, the log shows <strong>42</strong>. This verifies that the initial value was applied only when the helper was created. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/ha-logic-studio-pro-v0.1.122/ha_logic_studio_pro/tests/fixtures/iobroker-create-state.xml" target="_blank" rel="noreferrer">Blockly example</a></p><h3 id="imported-http-blocks" tabindex="-1">Imported HTTP blocks <a class="header-anchor" href="#imported-http-blocks" aria-label="Permalink to &quot;Imported HTTP blocks&quot;">​</a></h3><p>Select an approved HA REST command for the URL, timeout and request headers. The imported POST Content-Type is shown in the block.</p><h3 id="test-run-and-play" tabindex="-1">Test run and Play <a class="header-anchor" href="#test-run-and-play" aria-label="Permalink to &quot;Test run and Play&quot;">​</a></h3><p>Use simulation first. Save before Play and check actual results in the log.</p><h2 id="check-an-import-step-by-step" tabindex="-1">Check an import step by step <a class="header-anchor" href="#check-an-import-step-by-step" aria-label="Permalink to &quot;Check an import step by step&quot;">​</a></h2><ol><li>Enable <strong>Expert mode</strong> in the project menu. In the editor, open <strong>Expert tools → Paste ioBroker export</strong>.</li><li>Paste Blockly XML or an ioBroker JavaScript export with embedded Blockly data. Check the import and read which blocks need a mapping.</li><li>Open the import as a project and resolve the guidance on the affected blocks. For example, select the HA REST command that defines the headers and timeout for an imported POST.</li><li>Save and start with a <strong>test run</strong>. Use <strong>Play</strong> for live execution, check the <strong>log</strong>, and press <strong>Stop</strong> when finished.</li></ol><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>Replace or adapt unsupported placeholders before running the script.</p>',45)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
